pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // admissible domain: feeRate <= 5000 (initialization reverts above that)
        vm.assume(_feeRate <= 5000);
        // make sure initialized is false
        vm.assume(!c.initialized());

        vm.prank(address(this));
        try c.initialize(
            address(0x1),
            address(0x2),
            100,
            100,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        ) {
            // after successful initialization, stored feeRate must equal the provided _feeRate
            assertTrue(c.feeRate() == _feeRate);
        } catch {
            // initialization reverted; nothing to check
        }
    }
}

